const ID = 'jdnl-var-style';

const themes: Record<string, { bg: string; border: string; text: string; muted: string; accent: string; accentBg: string }> = {
  cream:   { bg: 'rgba(139,115,85,0.03)', border: 'rgba(139,115,85,0.12)', text: '#4a4035', muted: '#8a7e6e', accent: '#8b7355', accentBg: 'rgba(139,115,85,0.06)' },
  purple:  { bg: '#1e1c17', border: 'rgba(255,255,255,0.06)', text: '#d4cee0', muted: '#867e95', accent: '#9b7ec4', accentBg: 'rgba(155,126,196,0.08)' },
  gold:    { bg: '#1e1c17', border: 'rgba(255,255,255,0.06)', text: '#d4cee0', muted: '#867e95', accent: '#c9a96e', accentBg: 'rgba(201,169,110,0.08)' },
  teal:    { bg: '#1e1c17', border: 'rgba(255,255,255,0.06)', text: '#d4cee0', muted: '#867e95', accent: '#5ea0a7', accentBg: 'rgba(94,160,167,0.08)' },
  rose:    { bg: '#1e1c17', border: 'rgba(255,255,255,0.06)', text: '#d4cee0', muted: '#867e95', accent: '#c47b8b', accentBg: 'rgba(196,123,139,0.08)' },
};

function buildCSS(t: string) {
  const c = themes[t] || themes.cream;
  return `
.custom-var-update-box { margin:6px 0; border-radius:10px; padding:10px 14px; font-family:"DouyinSans",var(--font-main,sans-serif); font-size:11px; line-height:1.7; background:${c.bg}; border:1px solid ${c.border}; color:${c.text}; }
.custom-var-update-box summary { font-family:"寒蝉全圆体",var(--font-main,sans-serif); font-size:11px; letter-spacing:1px; cursor:pointer; color:${c.accent}; }
.custom-var-update-box .var-detail { color:${c.muted}; }
.custom-var-update-box summary:hover { opacity:0.8; }
`.trim();
}

function apply() {
  const t = (typeof localStorage !== 'undefined' && localStorage.getItem('jdnl_theme')) || 'cream';
  let el = document.getElementById(ID) as HTMLStyleElement | null;
  if (!el) { el = document.createElement('style'); el.id = ID; document.head.appendChild(el); }
  el.textContent = buildCSS(t);
}

apply();
if (typeof addEventListener !== 'undefined') addEventListener('storage', (e: StorageEvent) => { if (e.key === 'jdnl_theme') apply(); });
